package dev.mars.peegeeq.cache.rest.server;

import com.microsoft.playwright.Locator;
import com.microsoft.playwright.Page;
import com.microsoft.playwright.options.AriaRole;
import org.junit.jupiter.api.extension.RegisterExtension;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;
import java.nio.file.Path;
import java.util.List;
import java.util.Set;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import static org.junit.jupiter.api.Assertions.*;

/** Wave P5 real-browser scenarios for Pub/Sub subscription and publish behavior. */
class ManagementPubSubBrowserIT {
 @RegisterExtension static final ManagementBrowserPostgresWorker POSTGRES=new ManagementBrowserPostgresWorker(); @TempDir Path temporaryDirectory;
 private static final List<String>A=List.of("state process-local live messaging","explain non-durable subscriptions","enforce the configured-prefix 48-byte ASCII channel boundary","report channel UTF-8 bytes","reject a zero-entry subscription buffer","reject a 501-entry subscription buffer","default buffer to 20","disable empty subscription","enable valid subscription","explain PostgreSQL publish acceptance","report publish-channel UTF-8 bytes","report payload raw and wire bytes","return the complete server-confirmed subscription contract","accept an exact configured-prefix 48-byte ASCII channel","accept a 48-byte multibyte channel","reject a 51-byte multibyte channel before transport","accept the minimum one-entry buffer","accept the maximum 500-entry buffer","discard subscription on stop","return to subscribe after stop","publish accepted payload","clear payload after acceptance","deliver masked message metadata","show exact payload byte count","offer authorized payload reveal","reveal payload explicitly","hide payload explicitly","clear payload on visibility loss","clear retained state on stop","count multibyte UTF-8 exactly");
 static List<ManagementBrowserCase>scenarios(){return java.util.stream.IntStream.range(0,30).mapToObj(i->{List<String>operations=ops(i);Set<ManagementBrowserEvidence>evidence=operations.isEmpty()?Set.of(ManagementBrowserEvidence.VISIBLE_RESULT,ManagementBrowserEvidence.RESOURCE_CLEANUP):i>=24?Set.of(ManagementBrowserEvidence.VISIBLE_RESULT,ManagementBrowserEvidence.HTTP_OPERATION,ManagementBrowserEvidence.DATABASE,ManagementBrowserEvidence.DURABLE_AUDIT,ManagementBrowserEvidence.SENSITIVE_STATE,ManagementBrowserEvidence.RESOURCE_CLEANUP):Set.of(ManagementBrowserEvidence.VISIBLE_RESULT,ManagementBrowserEvidence.HTTP_OPERATION,ManagementBrowserEvidence.DATABASE,ManagementBrowserEvidence.DURABLE_AUDIT,ManagementBrowserEvidence.RESOURCE_CLEANUP);return new ManagementBrowserCase("PW-PUBSUB-%03d".formatted(i+2),"P5 Pub/Sub contract: "+A.get(i),ManagementBrowserArea.PUBSUB,i>=12?ManagementBrowserRisk.CRITICAL:ManagementBrowserRisk.HIGH,A.get(i),"The packaged console must "+A.get(i)+".","Stop subscriptions, hide payloads, reset PostgreSQL, and close transports and browser resources",operations,evidence);}).toList();}
 private static List<String>ops(int i){if(i<12||i==15)return List.of();if(i<=17)return List.of("createPubSubSubscription","streamPubSubMessages");if(i<=19)return List.of("createPubSubSubscription","streamPubSubMessages","deletePubSubSubscription");if(i<=21)return List.of("publishPubSubMessage");if(i<=24)return List.of("createPubSubSubscription","streamPubSubMessages","publishPubSubMessage");if(i<=27)return List.of("createPubSubSubscription","streamPubSubMessages","publishPubSubMessage","revealPubSubPayload");if(i==28)return List.of("createPubSubSubscription","streamPubSubMessages","publishPubSubMessage","revealPubSubPayload","deletePubSubSubscription");return List.of();}
 @ParameterizedTest(name="{0}")@MethodSource("dev.mars.peegeeq.cache.rest.server.ManagementBrowserSelection#pubSubScenarios")void pubSubScenario(ManagementBrowserCase s)throws Exception{int i=Integer.parseInt(s.id().substring(s.id().length()-3))-2;ManagementConsolePostgresFixture.run(temporaryDirectory,POSTGRES.postgres(),true,s.operations(),c->{Page p=c.page();p.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Pub/Sub").setExact(true)).click();assertThat(p.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Pub/Sub").setExact(true))).isVisible();verify(i,p);});}
 private static void verify(int i,Page p){switch(i){case 0->assertThat(p.getByText("Process-local live messaging",exact())).isVisible();case 1->assertThat(p.getByText("Subscriptions are non-durable and bounded. They end when this console session or setup closes.")).isVisible();case 2->{Locator channel=p.getByLabel("Channel",new Page.GetByLabelOptions().setExact(true));channel.fill("a".repeat(50));assertThat(channel).hasValue("a".repeat(48));assertThat(p.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Start subscription"))).isEnabled();}case 3->{p.getByLabel("Channel",new Page.GetByLabelOptions().setExact(true)).fill("abc");assertThat(p.getByText("3 / 48 UTF-8 bytes",exact())).isVisible();}case 4->{p.getByLabel("Channel",new Page.GetByLabelOptions().setExact(true)).fill("events");p.getByLabel("Buffer entries").fill("0");assertThat(p.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Start subscription"))).isDisabled();}case 5->{p.getByLabel("Channel",new Page.GetByLabelOptions().setExact(true)).fill("events");p.getByLabel("Buffer entries").fill("501");assertThat(p.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Start subscription"))).isDisabled();}case 6->assertThat(p.getByLabel("Buffer entries")).hasValue("20");case 7->assertThat(p.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Start subscription"))).isDisabled();case 8->{p.getByLabel("Channel",new Page.GetByLabelOptions().setExact(true)).fill("valid");assertThat(p.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Start subscription"))).isEnabled();}case 9->assertThat(p.getByText("Success means accepted by PostgreSQL; it does not prove subscriber delivery.")).isVisible();case 10->{p.getByLabel("Publish channel").fill("abc");assertThat(p.getByText("3 / 48 channel UTF-8 bytes",exact())).isVisible();}case 11->{p.getByLabel("Payload").fill("abc");assertThat(p.getByText("3 raw · 3 / 7500 wire bytes",exact())).isVisible();}case 12->{Locator subscription=start(p,"events",7);assertThat(subscription).containsText("Subscription: events");assertThat(subscription).containsText("Non-durable");assertThat(subscription).containsText("bounded to 7 messages");assertThat(subscription).containsText("CONNECTED");assertThat(p.getByText("No retained message metadata.",exact())).isVisible();}case 13->assertThat(start(p,"a".repeat(48),7)).isVisible();case 14->assertThat(start(p,"缓".repeat(16),7)).isVisible();case 15->{p.getByLabel("Channel",new Page.GetByLabelOptions().setExact(true)).fill("缓".repeat(17));assertThat(p.getByText("51 / 48 UTF-8 bytes",exact())).isVisible();assertThat(p.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Start subscription"))).isDisabled();}case 16->assertThat(start(p,"events",1)).containsText("bounded to 1 messages");case 17->assertThat(start(p,"events",500)).containsText("bounded to 500 messages");case 18->{start(p,"events",7);stop(p);assertThat(p.getByRole(AriaRole.STATUS)).containsText("discarded");}case 19->{start(p,"events",7);stop(p);assertThat(p.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Subscribe"))).isVisible();}case 20->{publish(p,"events","payload");assertThat(p.getByRole(AriaRole.STATUS)).containsText("Accepted by PostgreSQL");}case 21->{publish(p,"events","payload");assertThat(p.getByLabel("Payload")).hasValue("");}case 22->{message(p);assertThat(p.locator("tbody tr")).containsText("Masked");}case 23->{message(p);assertThat(p.locator("tbody tr")).containsText("14");}case 24->{message(p);assertThat(p.locator("button:has-text('Reveal payload')")).isVisible();}case 25->{reveal(p);assertThat(p.getByText("retained-value",exact())).isVisible();}case 26->{reveal(p);p.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Hide payload")).click();assertThat(p.getByText("retained-value",exact())).hasCount(0);}case 27->{reveal(p);p.evaluate("Object.defineProperty(document,'hidden',{value:true,configurable:true});document.dispatchEvent(new Event('visibilitychange'))");assertThat(p.getByText("retained-value",exact())).hasCount(0);}case 28->{reveal(p);stop(p);assertThat(p.getByText("retained-value",exact())).hasCount(0);assertThat(p.getByText("No retained message metadata.",exact())).hasCount(0);}case 29->{p.getByLabel("Channel",new Page.GetByLabelOptions().setExact(true)).fill("缓存");assertThat(p.getByText("6 / 48 UTF-8 bytes",exact())).isVisible();}default->throw new IllegalArgumentException();}}
 private static Locator start(Page p,String channel,int limit){p.getByLabel("Channel",new Page.GetByLabelOptions().setExact(true)).fill(channel);p.getByLabel("Buffer entries").fill(String.valueOf(limit));p.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Start subscription")).click();Locator subscription=p.getByRole(AriaRole.REGION,new Page.GetByRoleOptions().setName("Subscription: "+channel).setExact(true));assertThat(subscription).containsText("CONNECTED");return subscription;}private static void stop(Page p){p.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Stop subscription")).click();}private static void publish(Page p,String channel,String payload){p.getByLabel("Publish channel").fill(channel);p.getByLabel("Payload").fill(payload);p.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Publish").setExact(true)).click();}private static void message(Page p){start(p,"events",7);publish(p,"events","retained-value");assertThat(p.locator("tbody tr")).hasCount(1);}private static void reveal(Page p){message(p);p.locator("button:has-text('Reveal payload')").click();}private static Page.GetByTextOptions exact(){return new Page.GetByTextOptions().setExact(true);}
}
